import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.BwzYn71E.js";const p=JSON.parse('{"title":"Yazhen / Buckflower Release Machine","description":"","frontmatter":{"translationSource":{"title":"芽针/荞花放生机","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=CJl0m5vqcG6gAnt645AywF","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/yazhen-buckflower-release-machine"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/yazhen-buckflower-release-machine"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/yazhen-buckflower-release-machine"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/yazhen-buckflower-release-machine"}]]},"headers":[],"relativePath":"yazhen-buckflower-release-machine.md","filePath":"logistics/src/page-CJl0m5vqcG6gAnt645AywF.md"}'),r={name:"yazhen-buckflower-release-machine.md"};function n(d,e,o,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<div class="logistics-content"><span class="logistics-source-anchor" id="芽针-荞花放生机" aria-hidden="true"></span><h1 id="yazhen-buckflower-release-machine" tabindex="-1">Yazhen / Buckflower Release Machine <a class="header-anchor" href="#yazhen-buckflower-release-machine" aria-label="Permalink to &quot;Yazhen / Buckflower Release Machine&quot;">​</a></h1><blockquote><p>Source page ID: <code>CJl0m5vqcG6gAnt645AywF</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=CJl0m5vqcG6gAnt645AywF" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Person responsible: kokobird</p><p>Last updated: October 17, 2026.</p><p><span id="source-block-4FIjYVGEckjrq2ykWI0aGr"></span></p><span class="logistics-source-anchor" id="悲报-1-6版本起手册不再统计植物数量-本页面不再更新" aria-hidden="true"></span><h2 id="bad-news-since-version-1-6-the-handbook-no-longer-counts-plants-this-page-will-no-longer-be-updated" tabindex="-1">Bad News: Since Version 1.6, the Handbook No Longer Counts Plants; This Page Will No Longer Be Updated <a class="header-anchor" href="#bad-news-since-version-1-6-the-handbook-no-longer-counts-plants-this-page-will-no-longer-be-updated" aria-label="Permalink to &quot;Bad News: Since Version 1.6, the Handbook No Longer Counts Plants; This Page Will No Longer Be Updated&quot;">​</a></h2><blockquote><p>Aimed for 2.1 billion Yazhen; perished in the version 1.6 update, leaving the Type-II disposal machine to posterity.</p></blockquote><p>The original content follows.</p><hr><p>What is this? Use the production line&#39;s own consumption and trash bins to produce as much Buckflower or Yazhen as possible, pushing the handbook&#39;s counters to absurd heights—<s>and giving yj&#39;s servers a fright</s>.</p><p>Practical value: none. Just bored out of my mind.</p><p><span id="source-block-1kk1rCMRtWKBHVB1yK3YIW"></span></p><span class="logistics-source-anchor" id="当前功德-4-32m-day放生速度" aria-hidden="true"></span><h2 id="current-merit-4-32m-day-release-rate" tabindex="-1">Current Merit: 4.32M/day Release Rate <a class="header-anchor" href="#current-merit-4-32m-day-release-rate" aria-label="Permalink to &quot;Current Merit: 4.32M/day Release Rate&quot;">​</a></h2><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d75ef061d2c1f501.q90-06e36d1c0c2d81f2.webp" alt="Yazhen / Buckflower Release Machine"></p><p>MAN, WHAT CAN I SAY?</p><p>In practice, available area is the main limit; water is mostly plentiful, though quite a lot of stuff must be demolished.</p><p>This scheme essentially uses all the space around a full-rate battery line + 4 small Chubby Lung lines + 360 Xiranite production.</p><p>Four Chubby Lung lines currently redeem all the vouchers. We will worry about the future later.</p><p>One month idling reaches 1.3E; 16 months reaches 21E.</p><details><summary>Thunderous images</summary><p>We do not produce water; we merely transport it from nature.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cfa5acd9764f9b7a.q90-b92db5a14b8bf468.webp" alt="Yazhen / Buckflower Release Machine"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-769c19b6eb95b58c.q90-eb7ca05fbe941c03.webp" alt="Yazhen / Buckflower Release Machine"></p></details><details><summary>Full views of all four bases; they are not particularly dense.</summary><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8c39e92fe0baadbb.q90-166e176243137c35.webp" alt="Yazhen / Buckflower Release Machine"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ed169ba92b684a97.q90-d29efbe42157e641.webp" alt="Yazhen / Buckflower Release Machine"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-973350c637404031.q90-12f7170d52ee1914.webp" alt="Yazhen / Buckflower Release Machine"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-68de11c4e0741951.q90-2a4ec69d2d598239.webp" alt="Yazhen / Buckflower Release Machine"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-f8b97cbeef801bf7.q90-e89ed2c88441aeb4.webp" alt="Yazhen / Buckflower Release Machine"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-913cede2ac17471b.q90-51f20438aaf1a7ae.webp" alt="Yazhen / Buckflower Release Machine"></p><p>Apart from this section and one seed-picking setup, the main base contains the other Xircon, Cuprium Ore and similar lines. Everything from the Sky King Flats sub-base has been moved here to make batteries and Xiranite.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-bb2e95d108efd0f8.q90-35af2a0acea1eab2.webp" alt="Yazhen / Buckflower Release Machine"></p></details><p><span id="source-block-wKbDrdAMIqNijkI2xzbedp"></span></p><span class="logistics-source-anchor" id="一些计算" aria-hidden="true"></span><h2 id="some-calculations" tabindex="-1">Some Calculations <a class="header-anchor" href="#some-calculations" aria-label="Permalink to &quot;Some Calculations&quot;">​</a></h2><p>Time-scale constant: 1 year = 518400 minutes.</p><p>At 1000/m, idling for 1 year = 5.184 hundred million.</p><p>Reaching 2.1 billion in 1 year requires 4050/m.</p><details><summary>Friends…</summary><p><span class="mark-purple">A journey of a thousand miles begins with a single step!!!!!</span></p></details><p>With no trash bins in the Valley, maximum Buckflower output can be calculated directly from outpost voucher production—<s>surely nobody can manually clear storage every day for ten years</s>. Calculation pending………</p><p><u>Wuling can use Yazhen/Buckflower in Xiranite production. We need to determine whether that is more worthwhile than using efficient recipes and spending the spare power on releasing plants.</u></p><p><s>We could even stop refining Cuprium and spend all the power on releasing plants.</s></p><p><span id="source-block-tUwczI3yPlWEBlL2znQtkE"></span></p><span class="logistics-source-anchor" id="方案a1-使用传统垃圾桶的放生单元" aria-hidden="true"></span><h2 id="scheme-a1-release-unit-using-traditional-trash-bins" tabindex="-1">Scheme A1: Release Unit Using Traditional Trash Bins <a class="header-anchor" href="#scheme-a1-release-unit-using-traditional-trash-bins" aria-label="Permalink to &quot;Scheme A1: Release Unit Using Traditional Trash Bins&quot;">​</a></h2><p>Power: 370 (seed picking 4x30 + shredding 10 + Expanded Crucible 200 + Fluid Pumps 4x10). Releases 180/m Yazhen, approximately because trash bins are unstable.</p><p>Alternatively, release 120/m Buckflower.</p><p>I will optimize the layout when I have time.</p><p>Arknights: Endfield blueprint [Unnamed Blueprint], sharing code EF018OI434452127UI73. Copy and use in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5bdc89c09984d915.q90-e82475e320b44730.webp" alt="Yazhen / Buckflower Release Machine"></p><p><span id="source-block-bt6vhcyltZuwjCeeA4pjQG"></span></p><span class="logistics-source-anchor" id="方案a2-使用传统垃圾桶的放生机mkii" aria-hidden="true"></span><h2 id="scheme-a2-traditional-trash-bin-release-machine-mk-ii" tabindex="-1">Scheme A2: Traditional-Trash-Bin Release Machine Mk II <a class="header-anchor" href="#scheme-a2-traditional-trash-bin-release-machine-mk-ii" aria-label="Permalink to &quot;Scheme A2: Traditional-Trash-Bin Release Machine Mk II&quot;">​</a></h2><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4fe9ed3106ec5da5.q90-c0b287488ada8b59.webp" alt="Yazhen / Buckflower Release Machine"></p><p>Shown are two dual-core Jincao release machines Mk II. The remaining vacant slot in each destruction crucible is used to destroy Yazhen Seeds, effectively adding 60/m Yazhen destruction capacity per core.</p><p>Each core, meaning each crucible, now reaches 150/m Yazhen release.</p><p>Of course, Yazhen does not produce any high-tier product here. Making Yazhen Syringe [C] would require large quantities of Ferrium and be pointless; otherwise destroying high-tier products directly would be more worthwhile.</p><p>Another benefit is separating Yazhen Seed production, potentially convenient for some layouts.</p><p><span id="source-block-eRROcRGB6GxubBPz9zJwgI"></span></p><span class="logistics-source-anchor" id="部分模块" aria-hidden="true"></span><h2 id="some-modules" tabindex="-1">Some Modules <a class="header-anchor" href="#some-modules" aria-label="Permalink to &quot;Some Modules&quot;">​</a></h2><p><span id="source-block-94Kfh0hnSGG5VQio7CR9Bo"></span></p><span class="logistics-source-anchor" id="_180芽针种子模块" aria-hidden="true"></span><h3 id="_180-yazhen-seeds-module" tabindex="-1">180 Yazhen Seeds Module <a class="header-anchor" href="#_180-yazhen-seeds-module" aria-label="Permalink to &quot;180 Yazhen Seeds Module&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2aa0a3cb59153c64.q90-ff3790c4a7ec26f0.webp" alt="Yazhen / Buckflower Release Machine"></p><p>27*27 including the outermost ring of water pipes. Unsure whether direct seed production or multi-core aquatic planting followed by separate seed picking is better.</p><p><span id="source-block-gu0ivtX5FdkFSjgN843mHk"></span></p><span class="logistics-source-anchor" id="_240芽针种子模块" aria-hidden="true"></span><h3 id="_240-yazhen-seeds-module" tabindex="-1">240 Yazhen Seeds Module <a class="header-anchor" href="#_240-yazhen-seeds-module" aria-label="Permalink to &quot;240 Yazhen Seeds Module&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-242170f8678c4281.q90-791328adab5f498a.webp" alt="Yazhen / Buckflower Release Machine"></p><p>26*36, provided by 断懒; somewhat better area utilization than the preceding 180-core module.</p><p><span id="source-block-SLSTLDdgzdAprbh7ImJI7r"></span></p><span class="logistics-source-anchor" id="产物地均产值分析" aria-hidden="true"></span><h2 id="product-value-per-unit-area" tabindex="-1">Product Value per Unit Area <a class="header-anchor" href="#product-value-per-unit-area" aria-label="Permalink to &quot;Product Value per Unit Area&quot;">​</a></h2><p>Yazhen output is currently constrained mainly by land. To redeem all Stock Bills while maximizing Yazhen, identify products with the highest value per unit area. Machines handling only gas/fluid can be placed outside the base and excluded from occupied area.</p><p>First, roughly estimate from the machinery required by each product:</p><table tabindex="0"><thead><tr><th>Production module</th><th>Machine count</th><th>Machine area</th><th>Value per minute</th><th>Value per unit area</th></tr></thead><tbody><tr><td>30 Cuprium</td><td>1 Refining Unit</td><td>9</td><td>-</td><td>-</td></tr><tr><td>30 Cuprium Part</td><td>1 Fitting Unit, 1 Refining Unit</td><td>2x9=18</td><td>30</td><td>1.67</td></tr><tr><td>60 Xiranite (Forge; all unspecified entries below use the Forge)</td><td>1 Planting Unit, 1 Seed-Picking Unit, 2 Forges, 1 Refining Unit<br>(forgot to count the Gas Dispersing Unit)</td><td>4*25+9=109</td><td>60</td><td>0.55</td></tr><tr><td>60 Xiranite (Xiragen)</td><td>2 Solid-Gas Transmuting Units</td><td>50</td><td>60</td><td>1.2</td></tr><tr><td>90 Dense Originium Powder</td><td>3 Grinding Units, 7 Shredding Units, 2 Planting Units, 1 Seed-Picking Unit</td><td>210</td><td>-</td><td>-</td></tr><tr><td>12 small batteries</td><td>60 Xiranite + 180 powder</td><td>2*210+109=529</td><td>300</td><td>0.57</td></tr><tr><td>6 small Chubby Lung</td><td>60 Xiranite + 120 Cuprium Part + 2 Refining Units, 2 Packaging Units, 1 Moulding Unit</td><td>109+4<em>18+5</em>9=226</td><td>600</td><td>2.65</td></tr><tr><td>12 SC batteries</td><td>90 Xiranite + 240 powder + 2 Packaging Units, 3 Expanded Crucibles, 1 Purification Unit, 2 Shredding Units, 2 Refining Units</td><td>1.5<em>109+8/3</em>210+5<em>30+25+4</em>9=934.5</td><td>648</td><td>0.69</td></tr><tr><td>60 Separator Core</td><td>30 Xiranite + 60 Cuprium + 1 Packaging Unit, 1 Moulding Unit</td><td>0.5*109+18+24+9=105.5</td><td>60</td><td>0.57</td></tr><tr><td>48 Xiragen</td><td>60 Xiranite + 2 Solid-Gas Transmuting Units</td><td>109+2*25=159</td><td>-</td><td>-</td></tr><tr><td>24 Heavy Xiranite</td><td>132 Xiragen + 60 Separator Core + 2 Purification Units, 2 Solid-Gas Transmuting Units, 1 Gas Dispersing Unit</td><td>132/48<em>159+105.5+4</em>25+9=651.75</td><td>648</td><td>0.99</td></tr><tr><td>12 Hetonite Part</td><td>36 Xiragen + 60 Separator Core + 240 Cuprium + 6 Solid-Gas Transmuting Units, 2 Purification Units, 1 Gas Dispersing Unit</td><td>36/48<em>159+105.5+8</em>25+9=433.75</td><td>576</td><td>1.33</td></tr><tr><td>12 Pyrrolite Part (Gas Reactor Globes/Acridgen outside)</td><td>12 Hetonite Part + 66 Xiragen</td><td>433.75+48/66*159=549.38</td><td>840</td><td>1.53</td></tr><tr><td>12 Pyrrolite Part (nothing outside)</td><td>Above + 2 Gas Reactor Globes, 1 Gas Dispersing Unit, 1 Reactor Crucible, 1 Fluid-Gas Transmuting Unit</td><td>549.38+4*25+9=658.38</td><td>840</td><td>1.28</td></tr><tr><td>24 Cuprium-based medicine</td><td>480 Cuprium + 2 Reactor Crucibles, 2 Seed-Picking Units, 2 Planting Units, 2 Shredding Units, 8 Fitting Units, 4 Moulding Units, 4 Packaging Units, 4 Filling Units</td><td>16<em>9+6</em>25+14<em>9+8</em>24=612</td><td>528</td><td>0.86</td></tr><tr><td>24 Yazhen Syringe [C]</td><td></td><td></td><td>384</td><td>Hopeless</td></tr></tbody></table><p>Although Cuprium Parts have high value per area, making nothing else fills storage in under a day. Their rate should in principle not exceed 60 (</p><p>Next is the gas-route Cuprium-parts line. Two sub-base outposts can consume 14.51 Pyrrolite Part, reducing the area wasted by machines below full rate.</p><p>For generation instead, SC batteries give 3200/934.5=3.42 versus small batteries&#39; 1600/529=3.02. SC batteries are slightly better. Essentially SC batteries are better for both generation and vouchers, though their voucher value still loses to Heavy Xiranite.</p><p>This gives a fairly good plan for 1716/m Stock Bills: 12 Pyrrolite Part, 12<em>70=840; 6 Hetonite Part, 6</em>48=288; 24 Heavy Xiranite, 648. Total value 840+288+648=1776 meets demand.</p><p>Inputs: 12 Pyrrolite Part = 300 Cuprium + 30 Xiranite + 96 Xiragen; 6 Hetonite Part = 150 Cuprium + 15 Xiranite + 18 Xiragen; 24 Heavy Xiranite = 60 Cuprium + 30 Xiranite + 132 Xiragen. Total: 510 Cuprium + 75 Xiranite + 246 Xiragen.</p><p>Power generally uses 4.5 SC batteries or 9 small batteries. The former corresponds to 36 Xiranite and 90 powder, the latter 45 Xiranite and 135 powder. The SC-battery scheme produces 22.5 Xircon and needs only one Expanded Crucible and one ordinary crucible; perhaps the Purification Unit can also be omitted, consuming 45 Xiranite.</p><p>With the solid-gas route, total Xiranite consumption is about 220, allowing 8 Forges.</p><p>Note: batteries can be moved from the Valley, but that is troublesome; besides, when the Valley closes in next year&#39;s 2.0, you will have to behave.</p><p>Next compare the Yazhen count from making Xiranite with replacing the same area with destruction machines. For the type-I destruction machine, 180pm Yazhen count requires 4 seed-picking sets, 2 Shredding Units, 1 Stash and 2 Expanded Crucibles, occupying 287. 60 Xiranite occupies 109 and gives 60pm Yazhen count, so destruction machines are slightly better.</p><p><span id="source-block-HrVAZjwGyIdDX8HZgQpNgS"></span></p><span class="logistics-source-anchor" id="待研究的问题" aria-hidden="true"></span><h2 id="questions-to-investigate" tabindex="-1">Questions to Investigate <a class="header-anchor" href="#questions-to-investigate" aria-label="Permalink to &quot;Questions to Investigate&quot;">​</a></h2><p>We need more efficient trash bins!!!!!!!!!!!!!!!!!</p><p><span id="source-block-Ob2Yi7sdI8lJWiclurypqr"></span></p><span class="logistics-source-anchor" id="参考资料" aria-hidden="true"></span><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><span id="source-block-8cm8BKdhfLmsLfvL8yLneQ"></span></p><span class="logistics-source-anchor" id="蓝图" aria-hidden="true"></span><h3 id="blueprints" tabindex="-1">Blueprints <a class="header-anchor" href="#blueprints" aria-label="Permalink to &quot;Blueprints&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Author</th><th>BV</th><th>Blueprint code</th></tr></thead><tbody><tr><td>Four-core aquatic-planting module (18*18)</td><td>断懒</td><td>BV1Y6LU6PE31</td><td>[4 Aquatic Planting (Aesthetic Version)]EF018OI4EuA9i1o5UI73 <br>[4-Core Aquatic Plants]EF012UOeA5aI0894eIOo</td></tr><tr><td>720/m Buckflower charcoal production for Xiranite</td><td>ssnighter</td><td></td><td>[Xiranite Upper (First)] sharing code EF01E75207E57oee23uIa [Xiranite Lower (Second)] sharing code EF01A67iu6A76Eee19ieO</td></tr><tr><td>9-core aquatic plants</td><td>ssnighter</td><td></td><td>EF01u28IU2u820a58AoOU</td></tr><tr><td>Densely tiled Buckflower</td><td>断懒</td><td>BV11T4D69EKi</td><td>See video</td></tr><tr><td>6-core aquatic plants</td><td>咸鱼</td><td>BV1aWV56cESJ</td><td><br><br></td></tr><tr><td>Trash can</td><td>pl</td><td>Void Stash: The Last Piece of the Puzzle for Full Storage</td><td>[Void Stash v3] sharing code EF011I9AaO3aaUeO30O7</td></tr></tbody></table><blockquote><p>Translation note: “Release” retains the author’s humorous term for producing and destroying plants. “Cuprium-based medicine” means Jincao Tea or Yazhen Syringe [A]; this table does not specify the plant needed to choose one. The source’s Jincao/Yazhen wording and numerical expressions, including apparent arithmetic discrepancies, are preserved. E is the source notation for one hundred million.</p></blockquote></div>',1)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
